import{b as i,O as a,g as t,j as h}from"./chunks/framework.DSt9LnBW.js";const o=JSON.parse('{"title":"react项目中token失效路由跳转处理","description":"在react中有两种路由模式，分别是 hash 和 history，为了方便大家理解，我们先来了解下这两个路由使用hash模式下的URL，网络路径中会有一个#号进行拼接，而history没有带 # hash能够兼容到IE8，history只能够兼容到IE10 hash是通过window.onhashchange的方式进行监听变化，从而实现无刷新跳转，每次hash变化都会触发网页跳转，也就是浏览器的前进和后退，虽然hash会改变URL，但是不会触发页面重新加载。简而言之所有页面的跳转都是在客户端进行的，跳转的过程不算是一次http请求，所以这种模式对SEO优化是很不友好的。","frontmatter":{"date":"2026-06-09T00:00:00.000Z","tags":["React","鉴权"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/frontend/token-expire-redirect/index.md","filePath":"个人博客/前端/27.react项目中token失效路由跳转处理.md","lastUpdated":1790295671000}'),n={name:"blog/frontend/token-expire-redirect/index.md"};function k(l,s,p,e,r,E){return a(),t("div",null,[...s[0]||(s[0]=[h("",33)])])}const g=i(n,[["render",k]]);export{o as __pageData,g as default};
